CREATE DATABASE IF NOT EXISTS focus_os CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE focus_os;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) NOT NULL UNIQUE,email VARCHAR(190) UNIQUE,password_hash VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,mode ENUM('focus','short','long') NOT NULL,duration_seconds INT UNSIGNED NOT NULL,started_at DATETIME NOT NULL,ended_at DATETIME,completed BOOLEAN DEFAULT FALSE,INDEX(user_id,started_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS goals(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,goal_date DATE NOT NULL,daily_minutes SMALLINT UNSIGNED DEFAULT 120,completed_minutes SMALLINT UNSIGNED DEFAULT 0,UNIQUE(user_id,goal_date),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS badges(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) UNIQUE,title VARCHAR(100),description VARCHAR(255),xp_reward SMALLINT UNSIGNED DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_badges(user_id BIGINT UNSIGNED NOT NULL,badge_id BIGINT UNSIGNED NOT NULL,earned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,badge_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(badge_id) REFERENCES badges(id) ON DELETE CASCADE) ENGINE=InnoDB;
